  void initSession();            ///< sensitiveIspDetected = 0; maxTxRateIndexForSensitiveIsp = 14
  void loadParams(char* parser); ///< 295 Vparser_read_int / _float calls (pcm_parameters_load.cpp)
  void setToDefault();
  void loadModemParamsData(); ///< the modem parameters (params->...) override a few of the defaults
